create or replace function catalog._product_readiness_is_ready(
  p_has_base_unit boolean,
  p_has_images boolean,
  p_has_stock boolean,
  p_has_base_price boolean,
  p_has_price_band boolean,
  p_has_required_custom_fields boolean,
  p_stock_mode text,
  p_base_price_mode text
)
returns boolean
language sql
immutable
as $$
  -- p_has_stock / p_stock_mode giữ cho tương thích chữ ký (G5-5).
  -- Images are recommended-only; stock lives in inventory module (not a catalog readiness blocker).
  select
    coalesce(p_has_base_unit, false)
    and coalesce(p_has_base_price, false)
    and coalesce(p_has_price_band, false)
    and coalesce(p_has_required_custom_fields, true);
$$;

revoke all on function catalog._product_readiness_is_ready(boolean, boolean, boolean, boolean, boolean, boolean, text, text)
  from public, anon;
grant execute on function catalog._product_readiness_is_ready(boolean, boolean, boolean, boolean, boolean, boolean, text, text)
  to authenticated, service_role;

-- Recompute denorm flag from existing fact_* without re-deriving operational facts.
update catalog.products p
set is_ready_to_sell = catalog._product_readiness_is_ready(
  p.fact_has_base_unit,
  p.fact_has_images,
  p.fact_has_stock,
  p.fact_has_base_price,
  p.fact_has_price_band,
  p.fact_has_required_custom_fields,
  p.fact_stock_mode,
  p.fact_base_price_mode
);
